import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"L1 应用开发指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/index.md","filePath":"zh/l1/index.md"}'),o={name:"zh/l1/index.md"};function c(i,t,h,l,n,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="l1-应用开发指南" tabindex="-1">L1 应用开发指南 <a class="header-anchor" href="#l1-应用开发指南" aria-label="Permalink to &quot;L1 应用开发指南&quot;">​</a></h1><p>如何编写、构建并交付 Open Cube OS 的 ring-3 程序 - 从一行服务 包装到一个完整的合并大应用。</p><p>一段话讲清应用模型：<code>ocos/l1apps/&lt;name&gt;/</code> 之下<strong>一条命令 = 一个 应用 = 一个文件夹</strong>，内含 <code>main.c</code>（+ 任何额外 <code>.c</code>）与 <code>i18n/{en,zh}.json</code>。构建机械化地发现文件夹（没有手写表），把 每个应用以独立环境编译方式对 <code>ocos/interface/</code> 编译，并把每个 镜像内嵌进内核的 <code>OC_USERPROGS[]</code> 程序注册表（今天有 284 个 程序）。运行时 <code>ush</code> 按名字 fork + execve 注册表程序；应用通过 <code>SYS_L1SVC</code> 系统调用（类别 + 操作 + 参数行 + 输出缓冲）触达 每个内核服务。</p><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./overview.html">overview</a></td><td>应用模型、分层、数量</td></tr><tr><td><a href="./surface-map.html">surface-map</a></td><td>每个 L1SVC 类别与操作、系统调用桥</td></tr><tr><td><a href="./app-anatomy.html">app-anatomy</a></td><td>main.c / crt0 / i18n / l1_wizard_api.h - 完整解剖</td></tr><tr><td><a href="./writing-apps.html">writing-apps</a></td><td>从源码到 <code>run</code> 的完整应用 - 教程</td></tr><tr><td><a href="./wizard-library.html">wizard-library</a></td><td>8 个大应用背后的共享向导原语</td></tr><tr><td><a href="./driver-block.html">driver-block</a></td><td>扩展块服务</td></tr><tr><td><a href="./driver-nic.html">driver-nic</a></td><td>扩展网卡服务</td></tr><tr><td><a href="./driver-snd.html">driver-snd</a></td><td>扩展声音服务</td></tr><tr><td><a href="./ota.html">ota</a></td><td>应用侧的 OTA/A-B 服务</td></tr><tr><td><a href="./solib-loader.html">solib-loader</a></td><td>树内 ld.so + ET_DYN 程序</td></tr><tr><td><a href="./tui-ext.html">tui-ext</a></td><td>TUI 服务表面</td></tr><tr><td><a href="./watchdog-health.html">watchdog-health</a></td><td>应用视角的看门狗与健康</td></tr></tbody></table><h2 id="每个应用提供的三扇门" tabindex="-1">每个应用提供的三扇门 <a class="header-anchor" href="#每个应用提供的三扇门" aria-label="Permalink to &quot;每个应用提供的三扇门&quot;">​</a></h2><p>8 个已合并的应用（<code>update</code>、<code>disk-tool</code>、<code>net-tool</code>、 <code>sound-tool</code>、<code>files</code>、<code>sysdiag</code>、<code>hwinfo</code>、<code>power</code>）确立了 三门契约 - 无参向导、<code>direct</code> 直通、经典操作分发。新应用可以 自由采纳它；向导原语只差一次 <code>#include &quot;l1_wizard_api.h&quot;</code>。</p>',6)])])}const f=d(o,[["render",c]]);export{m as __pageData,f as default};
